110	/* Submit button */
111	.submitBtn {
112	  display: inline-flex;
113	  align-items: center;
114	  justify-content: center;
115	  background-image: linear-gradient(90deg, #21cfff, #019ae6);
116	  color: #fff;
117	  font-family: 'Roobert PRO', Arial, sans-serif;
118	  font-size: 16px;
119	  font-weight: 700;
120	  line-height: 1.75rem;
121	  text-decoration: none;
122	  border-radius: 0.75rem;
123	  padding: 0.75rem 2rem;
124	  border: none;
125	  cursor: pointer;
126	  transition: filter 0.15s ease, opacity 0.15s ease;
127	  align-self: flex-start;
